INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN0100', '俺だけレベルアップな件', '2024年冬', 'PR0001', 'TVシリーズ', 12, '『俺だけレベルアップな件』（おれだけレベルアップなけん、朝: 나 혼자만 레벨업、英: Solo Leveling）は、原作・原案Chugong、作画DUBU（REDICE STUDIO）による韓国の小説、漫画、ウェブトゥーン。日本語版は韓国語版とはストーリーやキャラクターに差異がある。略称は「나혼렙」「俺レベ」。', 151807) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN0101', 'ダンジョン飯', '2024年冬', 'PR0002', 'TVシリーズ', 24, '『ダンジョン飯』（ダンジョンめし）は、九井諒子による日本の漫画作品。年10回刊漫画誌『ハルタ』（KADOKAWA）にてvolume11からvolume107まで連載。著者初の長編連載作品。', 153518) ON CONFLICT DO NOTHING;
