INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN0118', '愚かな天使は悪魔と踊る', '2024年冬', 'PR0017', 'TVシリーズ', 12, '『愚かな天使は悪魔と踊る』（おろかなてんしはあくまとおどる）は、アズマサワヨシによる日本の漫画作品。『電撃マオウ』（KADOKAWA）にて2016年8月号（6月27日発売）より連載中。略称は「かな天」。2021年11月に単行本第12巻が発売された際には、YouTubeのKADOKAWAオフィシャルチャンネルにて、本作のボイスコミックを公開。リーリヤが主役の本作初となるスピンオフ『愚かな天使は悪魔と', 164244) ON CONFLICT DO NOTHING;
