INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN0230', 'ばいばい、アース', '2024年夏', 'PR0058', 'TVシリーズ', 10, '『ばいばい、アース』（Bye Bye, Earth）は、冲方丁による日本のファンタジー小説。角川書店から2000年に刊行された。2007年から2008年にかけて角川文庫版が刊行された。イラストは天野喜孝、文庫版はキム・ヒョンテ。 メディアミックスとして、『ヤングキングアワーズ』（少年画報社）にて2020年3月号から2022年9月号まで麻日隆の作画によるコミカライズが連載された。また、テレビアニメ第', 157371) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN0231', 'この世界は不完全すぎる', '2024年夏', 'PR0085', 'TVシリーズ', 13, '『この世界は不完全すぎる』（このせかいはふかんぜんすぎる）は、左藤真通による日本の漫画。『コミックDAYS』（講談社）にて、2020年5月30日から連載中。', 163077) ON CONFLICT DO NOTHING;
