INSERT INTO characters (character_id, anime_id, name, description, age, gender, anilist_id) VALUES ('CH000105', 'AN0102', '綾小路清隆', '綾小路 清隆（あやのこうじ きよたか）は、衣笠彰梧によるライトノベル作品『ようこそ実力至上主義の教室へ』の主人公。作中の舞台となる高度育成高等学校の1年Dクラスに在籍する男子生徒。2年生編にて進級する。', 16, '男性', 123212) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, anilist_id) VALUES ('CH000106', 'AN0102', '坂柳有栖', '坂柳 有栖（さかやなぎ ありす）は、衣笠彰梧によるライトノベル作品『ようこそ実力至上主義の教室へ』の登場人物の一人。作中の舞台となる高度育成高等学校の1年Aクラスに在籍する女子高校生。2年生編にて進級する。', 16, '女性', 124691) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, anilist_id) VALUES ('CH000107', 'AN0102', '堀北鈴音', '堀北 鈴音（ほりきた すずね）は、衣笠彰梧によるライトノベル作品『ようこそ実力至上主義の教室へ』の登場人物の一人。作中の舞台となる高度育成高等学校の1年Dクラスに在籍する女子生徒。2年生編にて進級する。', 15, '女性', 123213) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, anilist_id) VALUES ('CH000108', 'AN0102', '一之瀬帆波', '一之瀬 帆波（いちのせ ほなみ）は、衣笠彰梧によるライトノベル作品『ようこそ実力至上主義の教室へ』の登場人物の一人。作中の舞台となる高度育成高等学校の1年Bクラスに在籍する女子生徒。2年生編にて進級する。', 17, '女性', 123216) ON CONFLICT DO NOTHING;
