INSERT INTO characters (character_id, anime_id, name, description, age, gender, anilist_id) VALUES ('CH000483', 'AN0181', 'セバスチャン・ミカエリス', 'セバスチャン・ミカエリス（Sebastian Michaelis, 生没年不詳）は、17世紀のフランスの宗教家。 エクソシストとして名をはせた人物である。天使の階級にたいして9の階級に分類される「悪魔の階級」というものを発表したことでも知られる。エクサン＝プロヴァンスの修道女（Axi-en‐p-rovence　Nuns）などで有名なイエズス会の大審問官。 エクサン＝プロヴァンスに於いて、当時16～', NULL, '男性', 10863) ON CONFLICT DO NOTHING;
