INSERT INTO characters (character_id, anime_id, name, description, age, gender, anilist_id) VALUES ('CH000487', 'AN0182', '砂狼シロコ', '砂狼 シロコ（すなおおかみ シロコ、韓国語: 스나오오카미 시로코、英語: Sunaookami Shiroko、中国語: 砂狼白子）は、NEXON Games開発・Yostar運営によるスマートフォン向けゲームアプリ『ブルーアーカイブ -Blue Archive-』に登場する架空の人物。 併せて、別世界線の同一存在『シロコ＊テラー』についても本項で記述する。', 16, '女性', 245672) ON CONFLICT DO NOTHING;
