INSERT INTO characters (character_id, anime_id, name, description, age, gender, anilist_id) VALUES ('CH000787', 'AN0246', '高倉健', '高倉 健（たかくら けん、英︰Ken Takakura、1931年（昭和6年）2月16日 - 2014年（平成26年）11月10日）は、日本の俳優・歌手。本名は小田 剛一（おだ たけいち）（または小田 敏政）、だが晩年は親族に剛一郎（ごういちろう）と名乗った。高倉プロモーション所属。 福岡県中間市出身。1998年（平成10年）に紫綬褒章・2006年（平成18年）に文化功労者・2013年（平成25年', NULL, '男性', 222593) ON CONFLICT DO NOTHING;
