INSERT INTO characters (character_id, anime_id, name, description, age, gender, anilist_id) VALUES ('CH000792', 'AN0247', 'エミリア', 'エミリア（Emilia ）は、ヨーロッパ系の女性名。エミリーなどに対応する。ローマのアエミリウス氏族（Aemilius ）に由来し、その縁でイタリアの地名にもなっている。', 14, '女性', 88572) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, anilist_id) VALUES ('CH000793', 'AN0247', 'ナツキ・スバル', 'ナツキ・スバル（菜月 昴、英: Subaru Natsuki）は、長月達平によるライトノベル『Re:ゼロから始める異世界生活』の登場人物であり、同作の主人公である。イラストは大塚真一郎が担当している。 スバルは、コンビニエンスストアからの帰路に突如異世界へ召喚された引きこもりの少年であり、新たな世界での生活に適応しようとする中で幾度となく死を経験するが、そのたびに「死に戻り」（英: Return', 17, '男性', 88573) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, anilist_id) VALUES ('CH000794', 'AN0247', 'ベアトリス', 'Height: 140 cm (4''7") Age: ~!400+ (Actual)!~  The caretaker of the library in Roswaal''s mansion.   She has a distinct way of speaking, adding "I suppose" (かしら, kashira) and "in fact" (のよ, no yo) at th', NULL, '女性', 90181) ON CONFLICT DO NOTHING;
