INSERT INTO characters (character_id, anime_id, name, description, age, gender, anilist_id) VALUES ('CH001008', 'AN0292', '越前リョーマ', '越前 リョーマ（えちぜん リョーマ）は、許斐剛作の漫画作品およびそれを原作としたアニメ『テニスの王子様』、『新テニスの王子様』に登場する架空の人物で、同作の主人公である。アニメ版の声優は皆川純子。実写映画版の俳優は本郷奏多。ミュージカル版の俳優はミュージカル・テニスの王子様/2ndシーズン/3rdシーズン/4thシーズン/ミュージカル・新テニスの王子様を参照。', NULL, '男性', 324) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, anilist_id) VALUES ('CH001009', 'AN0292', '手塚国光', '手塚国光（てづか くにみつ）は、許斐剛作の漫画作品およびそれを原作としたアニメ『テニスの王子様』、『新テニスの王子様』に登場する架空の人物である。アニメ版の声優は置鮎龍太郎。実写映画版の俳優は城田優。ミュージカル版の俳優はミュージカル・テニスの王子様/2ndシーズン/3rdシーズン/4thシーズン/ミュージカル・新テニスの王子様を参照のこと。', NULL, '男性', 325) ON CONFLICT DO NOTHING;
