INSERT INTO characters (character_id, anime_id, name, description, age, gender, anilist_id) VALUES ('CH001015', 'AN0293', '中瀬', '中瀬（なかせ、なかぜ）は日本の地名、姓。  中瀬 (石巻市) - 宮城県石巻市の中洲・町名。 中瀬 (深谷市) - 埼玉県深谷市の町名。 中瀬 (千葉市) - 千葉県千葉市美浜区の町名。 中瀬 (川崎市) - 神奈川県川崎市川崎区の町名。 中瀬 (寒川町) - 神奈川県高座郡寒川町の町名。 中瀬 (長岡市) - 新潟県長岡市の町名。 中瀬町 (沼津市) - 静岡県沼津市の町名。 中瀬 (浜松市)', NULL, '男性', 348302) ON CONFLICT DO NOTHING;
